      /* [리마스터] 패드로 고른 지점이 살아 있으면(마우스를 움직이면 풀린다 — 아래 입력 갈래) 남은 마우스 자리로 고른 것·가리킴을 덮지 않는다
       *   (2026-11-08 사장님 「월드에서 지점 이동시 카메라는 이동하는데 하이라이트는 안되고」 — 화면에 남은 마우스 자리가 매 틱 고른 것·하이라이트를 덮어 동그라미가 마우스 쪽 지점으로 갈 수도 있었다) */
