    function 걸기(f) {
      if (받[f]) return;
      받[f] = '받는중';
      Promise.resolve(상태.파일받아넣기(f)).then(function () { 받[f] = '끝'; }, function () { 받[f] = '실패'; });
    }
    var 준비 = true;
    var 파T = 'CSTLDATA/' + 이름 + '.TEC';
    if (!있나(파T)) {
      if (받[파T] === '실패' || 받[파T] === '끝') return true;           /* `.TEC` 가 없는 장소 */
      걸기(파T); return false;
    }
    var tec = null;
    try { tec = TWN.TEC파싱(상태.파일읽기(파T)); } catch (e) { return true; }
