    if (로그) 로그.정보('TOWN: 마을 ' + 이름 + ' 입장 — ' + t.twn.MAP이름 +
                        ' (' + t.twn.W + '×' + t.twn.H + ')' +
                        (t.tec ? ' · TEC 있음' : ' · TEC 없음'));
