      if (!페J.이벤트 && !마을EVE준비(상태, 다음J)) return { 진행: '장소 페이드 — 이벤트 파일 기다림', 장소: 다음J };
      var 보관J = t.좌표보관;
      var 진입J = t.진입인자;
