        상태.town.좌표 = MV0.들어설때좌표(보관J, Number(다음J) | 0, mJ, (페J.마지막스캔 | 0) || 0x50);
        상태.town.이벤트끝페이드 = 페J.끝페이드 || null;
        if (로그) 로그.정보('TOWN: EVE 끝 — 시작 장소 ' + 다음J + ' 로 돌아왔다 · 주인공 (' +
                            (상태.town.좌표 && 상태.town.좌표.x) + ',' + (상태.town.좌표 && 상태.town.좌표.y) + ')');
