                var 값D2 = 레D2 ? ((레D2[38] | 0) | ((레D2[39] | 0) << 8)) : 0;
                t클.구입확인 = SHk.구입확인화면(이름D2, 값D2);
                t클.구입확인.색인 = 색D; t클.구입확인.가격값 = 값D2;
                if (로그) 로그.정보('TOWN: 진열품 클릭 (' + 칸클.x + ',' + 칸클.y + ') — ' +
                                    '색인 ' + 색D + ' 「' + 이름D2 + '」 ' + 값D2 + ' ELD (0x1D1FC)');
