            if (고른 > 0 && !후보들.some(function (c) { return (c.번호 | 0) === 고른; })) {
              var oF = null;
              for (var mf = 0; mf < 살아.length; mf++)
                if ((살아[mf].번호 | 0) === 고른) { oF = 살아[mf]; break; }
              if (oF) 후보들.push({ 번호: 고른, 오브: oF,
                                    화면: OBJ.화면좌표(oF, 캠말, { x: 0, y: 0 }),
                                    프레임: (크기재기 ? 크기재기(oF.SPR, oF.방향) : null) || { w: 0, h: 0 } });
            }
